INSERT OR REPLACE INTO kb_sources(source_id,title,source_kind,scope,authority,status,location,captured_at,version_fingerprint,notes) VALUES
('S-2026-10-07-CL41-COMPATIBILITY-CLOSE','F2 compatibility preservation source audit','verification','Central Lodge CL-41 F2','Foundry read-only RegionBehavior hashes and authored campaign plan','active','work/foundry-playwright-harness/cl41-f2-readonly-runtime-preview-v001.page.js; work/lodge-campaign/PUZZLE-REGION-PLAN.md','2026-10-07','F2 8 Regions/4 behaviors, read-only PASS','F2 is a final encounter/ritual, not a conventional puzzle lock. Existing four observations are enabled and source-locked; F1-to-F2 destination exists; ritualStage ACTIVE_RITUAL_BASELINE and resolution UNRESOLVED. No F2 additions or gameplay canary. This meets the original CL-41 preserve-existing-four compatibility slice, not full ritual gameplay completion.'),
('S-2026-10-07-CL50-TRANSITION-INVENTORY','CL-50 global transition inventory of 21 Lodge Scenes','verification','Central Lodge CL-50','Playwright Assistant GM no-write entire 21 Scene Region scan','active','work/foundry-playwright-harness/cl50-transition-inventory-readonly-v001.page.js','2026-10-07','202 Regions/113 RegionBehaviors before CL-50 additions','Read-only audit found many transition anchors with zero behaviors; F1-to-F2 one known working-script source. T1/T2 mouth orientations explicitly unbound, N3 branch unlock unresolved. The label-based inventory includes some nontransition Regions and must not be treated as complete transit edge count.'),
('S-2026-10-07-CL50-T3-F1-TRAVEL','CL-50 T3 ancient passage to F1 ancient infernal threshold','verification','Central Lodge CL-50 T3/F1','Guarded Playwright APPLY and separate independent no-write FINAL VERIFY','active','work/foundry-playwright-harness/cl50-t3-f1-preview-v001.page.js; cl50-t3-f1-apply-v001.page.js; cl50-t3-f1-final-verify-v001.page.js','2026-10-07','Source SHA c179ae83855e6eb136a1225bfbb882ab9c6b7bcd3f0773df3654f82b2b23d6cb','Exact F1 arrival stableId dbx:central-lodge:f1:region:transition:t3-arrival and F1 flags transitions.t3Arrival provided route authority, overturning old pending-future-scene status. Added one GM confirmation teleport, separate PREVIEW PASS, 8/8 offline mock PASS, guarded APPLY PASS, independent FINAL VERIFY PASS. No gameplay canary. One-way to avoid auto-bounce.'),
('S-2026-10-07-CL50-T3-N3-RETURN','CL-50 T3 N3 branch return to underground depot','verification','Central Lodge CL-50 T3/N3','Guarded Playwright APPLY and separate independent no-write FINAL VERIFY','active','work/foundry-playwright-harness/cl50-t3-n3-return-preview-v001.page.js; cl50-t3-n3-return-apply-v001.page.js; cl50-t3-n3-return-final-verify-v001.page.js','2026-10-07','Source SHA 051c669835aaed94f0497ebe6e54590d37df97eceb271b611b0263ca95b8f963','T3 N3 mouth explicitly names stable Scene N3. N3 Branch Railway is known Region. One-way GM-confirmed return behavior created, PREVIEW PASS, 8/8 offline mock PASS, APPLY PASS, independent FINAL VERIFY PASS. Does not unlock or install N3-to-T3 connection. Ledger unchanged.');

